import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Cache for prepared statement templates - NOT actual PreparedStatements
    private static final String BASE_QUERY = "SELECT asset_id, hostname, owner, department, status FROM assets WHERE department = '";
    private static final String AUDIT_INSERT = "INSERT INTO audit_log (action, query_text, source_ip, timestamp) VALUES (?, ?, ?, NOW())";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        String department = req.getParameter("dept");
        String format = req.getParameter("format");
        String apiKey = req.getHeader("X-API-Key");

        if (apiKey == null || apiKey.isEmpty()) {
            resp.sendError(401, "Missing API key");
            return;
        }

        // Validate API key format (UUIDv4)
        if (!apiKey.matches("[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}")) {
            resp.sendError(403, "Invalid API key format");
            return;
        }

        if (department == null || department.isEmpty()) {
            resp.sendError(400, "Missing department parameter");
            return;
        }

        // Length check - but allows enough room for injection
        if (department.length() > 128) {
            resp.sendError(400, "Parameter too long");
            return;
        }

        // Blocklist check - intentionally incomplete
        String deptLower = department.toLowerCase();
        if (deptLower.contains("drop ") || deptLower.contains("truncate ") || deptLower.contains("alter ")) {
            resp.sendError(400, "Invalid characters in department");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // VULNERABLE: String concatenation SQL query
            String query = BASE_QUERY + department + "' ORDER BY hostname ASC";

            // Audit logging uses parameterized query (ironic)
            try (PreparedStatement auditStmt = conn.prepareStatement(AUDIT_INSERT)) {
                auditStmt.setString(1, "ASSET_QUERY");
                auditStmt.setString(2, query);
                auditStmt.setString(3, req.getRemoteAddr());
                auditStmt.executeUpdate();
            }

            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_id", rs.getString("asset_id"));
                row.put("hostname", rs.getString("hostname"));
                row.put("owner", rs.getString("owner"));
                row.put("department", rs.getString("department"));
                row.put("status", rs.getString("status"));
                results.put(row);
            }

            JSONObject response = new JSONObject();
            response.put("count", results.length());
            response.put("assets", results);
            resp.getWriter().write(response.toString());

        } catch (SQLException e) {
            logger.warning("Database error: " + e.getMessage());
            resp.sendError(500, "Internal server error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
